import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../icon/icon.component';
import { FACT_TABLE_CONSTANTS, FactTableColumn } from '../../../userpanel/interfaces/fact-table.interface';
import { ButtonComponent } from '../button/button.component';
import { BadgeComponent } from '../badge/badge.component';
import { SourceCardComponent } from '../source-card/source-card.component';
import { SharedViewComponent } from '../shared-view/shared-view.component';
import { SelectedContactComponent } from '../contacts/selected-contact/selected-contact.component';
import { SelectedTasksComponent } from '../tasks/selected-tasks/selected-tasks.component';
import { MatMenuModule } from '@angular/material/menu';
import { FactfileRes, factlistRes, IssueRes } from '../../../userpanel/interfaces/workspace.interface';
import { WorkspaceService } from '../../../userpanel/services/workspace/workspace.service';
import { selectedContactList, selectedTaskList } from '../../interfaces/issue.interface';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../services/communication/communication.service';
import { myTeamUsers, toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { FactService } from '../../services/fact/fact.service';
import { EmptyComponent } from '../empty/empty.component';
import { FactNoteComponent } from '../../../pdf/components/facts/fact-note/fact-note.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { FactboxComponent } from '../../../pdf/components/facts/factbox/factbox.component';
import { QuickPreviewComponent } from '../../../userpanel/components/quick-preview/quick-preview.component';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { CommonService } from '../../services/common/common.service';
import { DateShowComponent } from '../../../marking/components/fact/date-show/date-show.component';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { FactsheetService } from '../../../userpanel/services/factsheet/factsheet.service';

import { HighlightPipe } from '../../pipes/highlight.pipe';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'facttable',
  standalone: true,
  imports: [CommonModule, IconComponent, ButtonComponent, BadgeComponent, SourceCardComponent, SharedViewComponent, SelectedContactComponent,
    SelectedTasksComponent, MatMenuModule, EmptyComponent, FactNoteComponent, MatTooltipModule, FactboxComponent, QuickPreviewComponent, DateShowComponent, HighlightPipe, TranslateModule],
  templateUrl: './fact-table.component.html',
  styleUrl: './fact-table.component.scss'
})

export class FactTableComponent implements OnInit, OnChanges, OnDestroy {
  @Input() isHeader: boolean = true;
  @Input() isQFact: boolean = false;
  @Input() nCaseid: string;
  @Input() fact: factlistRes;
  @Input() tablecols: any;
  @Input() noteSearchText: string = ''; // For highlighting search terms
  jTexts: string[] = [];
  type: string = FACT_TABLE_CONSTANTS.defaultType;
  showsource: any;
  // right-side contextual peek panel type
  peekField: 'issues' | 'contacts' | 'tasks' | 'doclinks' | null = null;

  // Access icons from constants
  readonly up_icon: string = FACT_TABLE_CONSTANTS.icons.up;
  readonly down_icon: string = FACT_TABLE_CONSTANTS.icons.down;
  readonly group_icon: string = FACT_TABLE_CONSTANTS.icons.group;

  // Default sort-key mapping per column key, used defensively
  private readonly defaultSortKeys: Record<string, string> = FACT_TABLE_CONSTANTS.defaultSortKeys;
  
  // Column model aligned with workspace fact/Q fact definitions and prototype
  headercoloumns: FactTableColumn[] = FACT_TABLE_CONSTANTS.headerColumns;

  @Input() sourceData: FactfileRes[];

  @Input() issue_ls: IssueRes[] = [];
  @Output() OnEvent = new EventEmitter<toolEvents>();

  @Input() userList: myTeamUsers[] = [];
  // Optional preloaded counts - if provided, skip API calls
  @Input() contactCount?: number;
  @Input() taskCount?: number;
  @Input() linksCount?: number;
  
  selectedUsers: myTeamUsers[] = [];
  user_list = [];
  contact_list: selectedContactList[] = []
  task_list: selectedTaskList[] = [];
  factLinks: any[] = [];
  private _contactCount: number = 0;
  private _taskCount: number = 0;
  private _linksCount: number = 0;
  evsubscription: Subscription;
  isEditText: boolean = false;
  isEmpty: boolean = false;
  isShareLoading: boolean;
  nUserid: string;
  factPermissions: {
    bCanView: boolean,
    bCanEdit: boolean,
    bCanDelete: boolean,
    bCanReshare: boolean,
    bCanComment: boolean
  }

  // Simple sort state for header click
  activeSortKey: string | null = null;
  activeSortDir: 'asc' | 'desc' | null = null;

  // drag state for header reordering
  private dragStartIndex: number | null = null;


  constructor(private readonly wsService: WorkspaceService, private readonly cdr: ChangeDetectorRef,
    private readonly cs: CommunicationService,
    private readonly factservice: FactService, private readonly cf: CommonfunctionService,
    private readonly common: CommonService,
    private readonly factsheetService: FactsheetService,
    private readonly storage: SecureStorageService,
  ) {
    this.evsubscription = this.cs.functionCalled$.subscribe(async (data) => {
      if (data.type === 'SHOW-COLS') {
        this.tablecols = data.tablecols;
        if (this.tablecols?.length) {
          this.syncHeaderWithTableCols();
        }
        this.cdr.detectChanges();
      }
    });
  }

  // Always return an array for relevanceList for template safety
  get factRelevanceList(): string[] {
    if (!this.fact) return [];
    
    // Collect unique relevance values from all issues
    const relevanceSet = new Set<string>();
    
    // Check if we have issues with relevance data
    if (this.issue_ls && Array.isArray(this.issue_ls)) {
      this.issue_ls.forEach(issue => {
        if (issue.cRelevance) {
          relevanceSet.add(issue.cRelevance);
        }
      });
    }
    
    // If we collected relevance values from issues, return them
    if (relevanceSet.size > 0) {
      return Array.from(relevanceSet);
    }
    
    // Fallback to fact's single relevance value
    if (typeof this.fact.cRelevance === 'string' && this.fact.cRelevance) {
      return [this.fact.cRelevance];
    }
    
    return [];
  }

  // Return array of unique impacts from all issues
  get factImpactList(): Array<{id: number, count: number}> {
    if (!this.fact) return [];
    
    // Collect impact IDs and their counts from all issues
    const impactMap = new Map<number, number>();
    
    // Check if we have issues with impact data
    if (this.issue_ls && Array.isArray(this.issue_ls)) {
      this.issue_ls.forEach(issue => {
        if (issue.nImpactid) {
          const impactId = Number(issue.nImpactid);
          const currentCount = impactMap.get(impactId) || 0;
          impactMap.set(impactId, currentCount + 1);
        }
      });
    }
    
    // If we collected impact values from issues, return them
    if (impactMap.size > 0) {
      return Array.from(impactMap.entries()).map(([id, count]) => ({id, count}));
    }
    
    // Fallback to fact's single impact value
    if (this.fact.nImpactid) {
      return [{id: Number(this.fact.nImpactid), count: Number(this.fact.nImpactcount) || 1}];
    }
    
    return [];
  }

    getSidebarPdfUrl() {
      if (!this.showsource) return '';
      return this.cf.senitizeUrl(
        this.showsource.cFilepath || this.showsource.cPath,
        this.showsource.nBundledetailid,
        this.nCaseid,
        false, // isFullmode
        null,  // isLink (highlightModeType)
        1,     // pageNo
        false, // isRealtime
        false, // compareMode
        0,     // compareIndex
        '',    // linkExplorerMode
        '',    // linkExplorerType
        null,  // nRFSid
        null,  // nRDocid
        null,  // nRWebid
        true,  // isMyfile
        'MB',  // activesectiontype
        this.showsource.nSectionid,
        null,  // nPresentid
        false, // isHost
        '',    // jFilter
        1      // lineNo
      );
    }

  ngOnInit(): void {
    this.initializeComponent();
  }

  private async initializeComponent(): Promise<void> {
    this.nUserid = await this.storage.getUserId();
    if (this.fact) {
      // Start from the fact's jTexts but normalize so that index 0
      // holds the first non-empty entry (if any). This avoids a
      // blank display when text lives in later entries.
      this.jTexts = Array.isArray(this.fact.jTexts) ? [...this.fact.jTexts] : [];
      const firstNonEmpty = this.jTexts.find(t => {
        if (t === null || t === undefined) {
          return false;
        }
        const s = String(t).trim();
        return !!s;
      });

      if (firstNonEmpty !== undefined) {
        this.jTexts[0] = String(firstNonEmpty);
      }

      const hasNonEmpty = firstNonEmpty !== undefined;
      this.isEmpty = !hasNonEmpty;
      this.fact.cName = this.fact.cName ? this.fact.cName : this.fact.cFilename;
      
      // Initialize counts from Input properties if provided, otherwise load from API
      this.initializeCounts();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.tablecols?.length) {
      this.syncHeaderWithTableCols();
    }

    // When the bound fact row changes (e.g. after API refresh or
    // sorting/grouping in the parent), rebind note text and reload
    // per-row counts so values do not leak between rows.
    if (changes['fact']?.currentValue) {
      this.jTexts = Array.isArray(this.fact?.jTexts) ? [...this.fact.jTexts] : [];
      const firstNonEmpty = this.jTexts.find(t => {
        if (t === null || t === undefined) {
          return false;
        }
        const s = String(t).trim();
        return !!s;
      });

      if (firstNonEmpty !== undefined) {
        this.jTexts[0] = String(firstNonEmpty);
      }

      const hasNonEmpty = firstNonEmpty !== undefined;
      this.isEmpty = !hasNonEmpty;
      this.fact.cName = this.fact.cName ? this.fact.cName : this.fact.cFilename;

      // Initialize counts from Input properties if provided
      this.initializeCounts();
    }

    // Update counts if they change via Input
    if (changes['contactCount']) {
      this._contactCount = this.contactCount ?? 0;
    }
    if (changes['taskCount']) {
      this._taskCount = this.taskCount ?? 0;
    }
    if (changes['linksCount']) {
      this._linksCount = this.linksCount ?? 0;
    }
  }

  ngOnDestroy(): void {
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
    this.evsubscription.unsubscribe();
  }

  private initializeCounts(): void {
    // Use provided Input counts if available, otherwise keep existing or set to 0
    if (this.contactCount === undefined) {
      // Reset to 0 and don't load - counts will be fetched on-demand when peek panel opens
      this._contactCount = 0;
    } else {
      this._contactCount = this.contactCount;
    }

    if (this.taskCount === undefined) {
      this._taskCount = 0;
    } else {
      this._taskCount = this.taskCount;
    }

    if (this.linksCount === undefined) {
      this._linksCount = 0;
    } else {
      this._linksCount = this.linksCount;
    }
  }

  async getfactContact() {
    this.contact_list = await this.wsService.getFactContact(this.fact.nFSid);
    this._contactCount = this.contact_list ? this.contact_list.length : 0;
  }

  async getfactTask() {
    const res: any = await this.wsService.getFactTask(this.fact.nFSid);
    this._taskCount = 0;
    this.task_list = res[0] || [];
    this.task_list.forEach(a => {
      let user = [];
      if (res[1]) {
        user = res[1].filter(b => b.jTaskid.includes(a.nTaskid));
      }
      a['teamlist'] = user || [];
      this.task_list.forEach(a => {
        let remiders = [];
        if (res[2]) {
          const row = res[2].filter(b => b.nTaskid === a.nTaskid);
          remiders = row.length ? row[0].jReminders : [];
        }
        a['jReminders'] = remiders || [];
      });
    });
    this._taskCount = this.task_list ? this.task_list.length : 0;
  }

  async getFactLinks() {
    this._linksCount = 0;
    this.factLinks = [];
    const res: any = await this.factsheetService.getFactLinks<any[]>(this.fact.nFSid);
    if (res && Array.isArray(res.value)) {
      this.factLinks = res.value;
      this._linksCount = this.factLinks.length;
    }
  }

  // Safely derive counts for contacts, tasks, and links for display
  getContactsCount(): number {
    return this._contactCount || 0;
  }

  getTasksCount(): number {
    return this._taskCount || 0;
  }

  getLinksCount(): number {
    return this._linksCount || 0;
  }

  // Open sidebar peek panels from header cells
  openIssuesPeek() {
    this.peekField = 'issues';
    this.cdr.detectChanges();
  }

  async openContactsPeek() {
    await this.getfactContact();
    this.peekField = 'contacts';
    this.cdr.detectChanges();
  }

  async openTasksPeek() {
    await this.getfactTask();
    this.peekField = 'tasks';
    this.cdr.detectChanges();
  }

  openDocLinksPeek() {
    this.peekField = 'doclinks';
    this.cdr.detectChanges();
  }

  async getuser_list() {
    this.isShareLoading = true;
    if (!this.userList?.length) {
      this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    }
    this.selectedUsers = await this.factservice.getFactShare(this.fact.nFSid);
    this.userList.forEach(f => f.isSelected = this.selectedUsers.some(m => m.nUserid === f.nUserid))

    this.factPermissions = await this.factservice.getFactPermissions(this.fact.nFSid, this.nUserid)


    this.isShareLoading = false;
    this.cdr.detectChanges();
  }

  OnSourceEvent(event, flag) {
    // Emit a custom event to parent to open PDF preview and close Fact Sheet
    if (event.event === 'VIEW-SOURCE') {
      this.OnEvent.emit({ event: 'OPEN-PDF-SIDEBAR', data: event.data });
      return;
    }
    this.OnEvent.emit(event);
  }

  closePeek() {
    this.peekField = null;
    this.cdr.detectChanges();
  }

  sortList(x, col) {
    this.OnEvent.emit({ event: 'SORT', data: { col: col, typ: x } });
  }

  // Map workspace table column visibility into header column model
  private syncHeaderWithTableCols(): void {
    if (!this.tablecols?.length) {
      return;
    }

    // First, update visibility and capture any explicit order index from workspace config
    let mapped = this.headercoloumns.map(col => {
      const matching = this.tablecols.find((t: any) => t.id === col.id || t.key === col.key);
      col.isshow = matching ? matching.isshow : false;
      // Persist an explicit order index if provided; fall back to existing id
      col.order = matching?.order === undefined ? (col.order ?? col.id) : matching.order;
      return col;
    });

    mapped = mapped.map((col: any) => {
      if (col.sortable && !col.sortKey && this.defaultSortKeys[col.key]) {
        col.sortKey = this.defaultSortKeys[col.key];
      }
      return col;
    });

    // Then, sort the column array itself by that order so
    // both header and body use the exact same sequence
    mapped = mapped.sort((a: any, b: any) => {
      const ao = a.order ?? a.id;
      const bo = b.order ?? b.id;
      return ao - bo;
    });

    this.headercoloumns = mapped;

    // Q Fact uses a reduced set of columns; hide Fact-only ones
    if (this.isQFact) {
      const qfactKeys = new Set(['created', 'note', 'issues', 'impact', 'relevance', 'source', 'actions']);
      this.headercoloumns = this.headercoloumns.map(col => {
        if (col.key && !qfactKeys.has(col.key)) {
          col.isshow = false;
        }
        return col;
      });
    }
  }

  onHeaderClick(col: any): void {
    if (!col) {
      return;
    }

    // If sortKey is missing, derive it from the default map using the column key
    if (!col.sortKey && this.defaultSortKeys[col.key]) {
      col.sortKey = this.defaultSortKeys[col.key];
    }

    if (!col.sortKey) {
      return;
    }

    if (this.activeSortKey === col.sortKey) {
      this.activeSortDir = this.activeSortDir === 'asc' ? 'desc' : 'asc';
    } else {
      this.activeSortKey = col.sortKey;
      this.activeSortDir = 'asc';
    }

    // Reuse existing SORT event contract expected by workspace components
    const sortType = this.activeSortDir === 'asc' ? 'A' : 'D';
    const sortCol = { nm: '', icon: null, typ: sortType, clmn: col.sortKey };
    this.sortList(sortType, sortCol);
  }

  onHeaderDragStart(event: DragEvent, index: number): void {
    if (!this.isHeader || !event.dataTransfer) {
      return;
    }
    this.dragStartIndex = index;
    event.dataTransfer.effectAllowed = 'move';
  }

  onHeaderDragOver(event: DragEvent): void {
    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = 'move';
    }
  }

  onHeaderDrop(event: DragEvent, dropIndex: number): void {
    event.preventDefault();
    if (this.dragStartIndex === null || this.dragStartIndex === dropIndex) {
      return;
    }

    const cols = [...this.headercoloumns];
    const [moved] = cols.splice(this.dragStartIndex, 1);
    cols.splice(dropIndex, 0, moved);
    this.headercoloumns = cols;
    this.dragStartIndex = null;
    this.cdr.detectChanges();

    // Propagate new column order to all fact tables via the
    // shared tablecols model so every row (each facttable
    // instance) uses the same header/body order.
    if (this.tablecols && Array.isArray(this.tablecols) && this.tablecols.length) {
      const orderByKey: Record<string, number> = {};
      this.headercoloumns.forEach((c: any, idx: number) => {
        if (c.key) {
          orderByKey[c.key] = idx;
        }
      });

      this.tablecols = this.tablecols.map((col: any) => {
        const key = col?.key ?? null;
        if (key && orderByKey.hasOwnProperty(key)) {
          return { ...col, order: orderByKey[key] };
        }
        return col;
      });

      // Broadcast the updated column config so all FactTable
      // instances resync via CommunicationService.
      this.cs.callFunction({ type: 'SHOW-COLS', tablecols: this.tablecols });
    }
  }

  async SaveNote(g) {
    // For QF and F, allow empty notes to be saved as empty.
    // If no updated texts were collected from the editor, fall back to jTexts
    // (which may itself be empty).
    if (!g.jUpdatedTexts?.length) {
      g.jUpdatedTexts = g.jTexts || [];
    }

    await this.factservice.updateFactNote({ nFSid: g.nFSid, jTexts: g.jUpdatedTexts })
    this.OnEvent.emit({ event: 'SUBMIT-NOTE', data: g });
    this.isEditText = false;
    this.cdr.detectChanges()
  }

  openToQFect() {
    let page = 1
    if (this.fact?.jLinktype?.pages?.length) {
      page = this.fact.jLinktype.pages[0]
    } else if (this.fact?.jLinktype?.start) {
      page = this.fact?.jLinktype?.start;
    }
    this.openfile(this.fact.nBundledetailid, page, this.fact.nFSid);
  }

  openfile(nBundledetailid, page, nFSid) {
    this.cf.openHyperLinkFile(nBundledetailid, this.nCaseid, null, null, false, page, null, nFSid)
  }

  addNote() {
    this.jTexts = this.jTexts?.length ? this.jTexts : [''];
    this.isEmpty = false;
    this.isEditText = true;
    this.cdr.detectChanges()

  }

  // Enter note edit mode with the current note value pre-populated
  startEditNote() {
    // If local jTexts is empty, seed it from the fact's existing note
    if (!this.jTexts?.length) {
      if (this.fact?.jTexts?.length) {
        this.jTexts = [...this.fact.jTexts];
      } else if (this.fact?.cFact) {
        this.jTexts = [this.fact.cFact];
      } else {
        this.jTexts = [''];
      }
    }

    this.isEditText = true;
    this.cdr.detectChanges();
  }

  getInitials(c: selectedContactList): string {
    if (!c) {
      return '';
    }
    const first = c.cFname ? c.cFname.charAt(0) : '';
    const last = c.cLname ? c.cLname.charAt(0) : '';
    return (first + last).toUpperCase();
  }

  getRelevanceColor(relevance: string | null | undefined): string {
    if (!relevance) {
      return '#6b7280'; // neutral gray
    }
    const v = relevance.toLowerCase();
    if (v === 'critical') {
      return '#ef4444';
    }
    if (v === 'high') {
      return '#f59e0b';
    }
    if (v === 'medium') {
      return '#10b981';
    }
    if (v === 'low') {
      return '#60a5fa';
    }
    return '#6b7280';
  }
}
